container_args:
set -euo pipefail
cat > /tmp/python3 <<'SH'
#!/bin/bash
if [ "${1:-}" = "-m" ] && [ "${2:-}" = "nim_llm_sdk.entrypoints.launch" ]; then
  shift 2
  exec /opt/nim/llm/.venv/bin/python3 - "$@" <<'PY'
import os
import runpy
import sys

site = os.path.normpath(os.path.join(os.environ.get("PYTHON_PATH", "/opt/nim/llm/.venv/bin"), "..", "lib", "python3.12", "site-packages"))
managed_links = {
    os.path.join(site, "outlines"): os.path.join(site, "outlines-1.2.5"),
    os.path.join(site, "outlines_core"): os.path.join(site, "outlines_core-0.2.11"),
}
_real_remove = os.remove
_real_symlink = os.symlink

def _same_link(dst: str, src: str) -> bool:
    try:
        return os.path.islink(dst) and os.path.normpath(os.readlink(dst)) == os.path.normpath(src)
    except OSError:
        return False

def _safe_remove(path: str, *args, **kwargs):
    dst = os.path.normpath(path)
    desired = managed_links.get(dst)
    if desired and _same_link(dst, desired):
        return None
    return _real_remove(path, *args, **kwargs)

def _safe_symlink(src: str, dst: str, *args, **kwargs):
    normalized_dst = os.path.normpath(dst)
    desired = managed_links.get(normalized_dst)
    if desired and os.path.normpath(src) == os.path.normpath(desired) and _same_link(normalized_dst, desired):
        return None
    return _real_symlink(src, dst, *args, **kwargs)

os.remove = _safe_remove
os.symlink = _safe_symlink
sys.argv = ["nim_llm_sdk.entrypoints.launch", *sys.argv[1:]]
runpy.run_module("nim_llm_sdk.entrypoints.launch", run_name="__main__")
PY
fi
exec /opt/nim/llm/.venv/bin/python3 "$@"
SH
chmod 0755 /tmp/python3
PATH="/tmp:${PATH}" exec /opt/nvidia/nvidia_entrypoint.sh /opt/nim/start_server.sh
